#!/usr/bin/env python3
"""Cover-specific image placement controls layered onto the native Design editor."""

def install(html):
    css=r'''<style id="d2-cover-asset-css">#d2-cover-image{display:none;margin-top:12px;padding-top:10px;border-top:1px solid #d9d3c7}.d2-cover-image-grid{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:5px}.d2-cover-image-grid button,.d2-cover-image-grid select,.d2-cover-image-grid input{width:100%;box-sizing:border-box;margin:0!important;padding:6px!important;font:9px Inter,sans-serif!important;border:1px solid #d9d3c7;background:#fbfaf6}.d2-cover-image-grid input[type=range]{padding:0!important}.d2-cover-image-note{margin-top:6px;color:#8b8579;font:9px/1.4 Inter,sans-serif}</style>'''
    panel=r'''<div id="d2-cover-image"><div class="d2-section-title">COVER IMAGE</div><div class="d2-cover-image-grid"><button id="d2-cover-place">Place artwork</button><button id="d2-cover-replace">Replace selected</button></div><input id="d2-cover-file" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/svg+xml" hidden><div class="d2-cover-image-grid"><button id="d2-cover-full">Full bleed</button><button id="d2-cover-framefit">Inside frame</button></div><div class="d2-cover-image-grid"><select id="d2-cover-fit"><option value="cover">Cover</option><option value="contain">Contain</option><option value="fill">Fill</option></select><button id="d2-cover-apply-fit">Apply fit</button></div><div class="d2-cover-image-grid"><input id="d2-cover-x" type="range" min="0" max="100" value="50" title="Crop X"><input id="d2-cover-y" type="range" min="0" max="100" value="50" title="Crop Y"></div><div class="d2-cover-image-grid"><button id="d2-cover-center-crop">Center crop</button><button id="d2-cover-apply-crop">Apply crop</button></div><div id="d2-cover-image-note" class="d2-cover-image-note">Artwork stays a replaceable structured image node.</div></div>'''
    js=r'''<script id="d2-cover-asset-js">(()=>{const q=id=>document.getElementById(id),panel=q('d2-cover-image');if(!panel)return;let replace=false,lastId=null;function isCover(){return active==='multiwrite-cover'}function pg(){return ws?.pages?.find(p=>p.id==='multiwrite-cover')}function selectedNode(){const id=selected?.id||lastId;return pg()?.nodes?.find(n=>n.id===id)}function refresh(){panel.style.display=isCover()?'block':'none';if(!isCover())return;const n=selectedNode(),img=n?.type==='image';q('d2-cover-replace').disabled=!img;q('d2-cover-full').disabled=!img;q('d2-cover-framefit').disabled=!img;q('d2-cover-fit').disabled=!img;q('d2-cover-apply-fit').disabled=!img;q('d2-cover-x').disabled=!img;q('d2-cover-y').disabled=!img;q('d2-cover-center-crop').disabled=!img;q('d2-cover-apply-crop').disabled=!img;if(img){q('d2-cover-fit').value=n.fit||'cover';q('d2-cover-x').value=n.crop_x??50;q('d2-cover-y').value=n.crop_y??50;q('d2-cover-image-note').textContent='Image · '+(n.asset_id||n.id)}else q('d2-cover-image-note').textContent='Select an image to crop, fit or replace.'}async function post(p){const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});if(!r.ok)return null;ws=await r.json();q('status').textContent='saved · r'+ws.revision+' · '+active;return ws}function canvasReload(){q('canvas').src=canvasUrl();setTimeout(refresh,80)}function choose(rep){replace=rep;q('d2-cover-file').value='';q('d2-cover-file').click()}q('d2-cover-place').onclick=()=>choose(false);q('d2-cover-replace').onclick=()=>choose(true);q('d2-cover-file').onchange=e=>{const f=e.target.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=async()=>{const uri=reader.result,n=selectedNode();if(replace&&n?.type==='image'&&n.asset_id){await post({op:'set_asset',page_id:'multiwrite-cover',asset_id:n.asset_id,patch:{uri,name:f.name,mime:f.type}})}else{const stamp=Date.now().toString(36),aid='cover-asset-'+stamp,nid='cover-image-'+stamp;await post({op:'place_image',page_id:'multiwrite-cover',asset:{id:aid,kind:'image',uri,name:f.name,mime:f.type},shape:{id:nid,type:'image',role:'cover-art',asset_id:aid,x:80,y:80,w:1040,h:1340,fit:'cover',crop_x:50,crop_y:50}});lastId=nid}canvasReload()};reader.readAsDataURL(f)};async function patch(p){const n=selectedNode();if(!n||n.type!=='image')return;await post({op:'set_node',page_id:'multiwrite-cover',id:n.id,patch:p});canvasReload()}q('d2-cover-full').onclick=()=>patch({x:0,y:0,w:1200,h:1500});q('d2-cover-framefit').onclick=()=>patch({x:80,y:80,w:1040,h:1340});q('d2-cover-apply-fit').onclick=()=>patch({fit:q('d2-cover-fit').value});q('d2-cover-center-crop').onclick=()=>{q('d2-cover-x').value=50;q('d2-cover-y').value=50;patch({crop_x:50,crop_y:50})};q('d2-cover-apply-crop').onclick=()=>patch({crop_x:+q('d2-cover-x').value,crop_y:+q('d2-cover-y').value});window.addEventListener('message',e=>{const m=e.data||{};if(m.page_id==='multiwrite-cover'&&(m.type==='dore-select'||m.type==='dore-selection-set')){lastId=m.id||m.primary||lastId;setTimeout(refresh,0)}});setInterval(refresh,500);refresh()})()</script>'''
    return html.replace('</head>',css+'</head>',1).replace('<p class="hint">Homepage and Journal are separate workspace pages.',''+panel+'<p class="hint">Homepage and Journal are separate workspace pages.',1).replace('</body>',js+'</body>',1)
